//! WASM tool wrapper implementing the Tool trait.//!//! Uses wasmtime::component::bindgen! to generate typed bindings from the WIT//! interface, ensuring all host functions are properly registered under the//! correct `near:agent/host` namespace.//!//! Each execution creates a fresh instance (NEAR pattern) to ensure//! isolation and deterministic behavior.use std::collections::HashMap;use std::sync::Arc;use std::time::{Duration, Instant};use async_trait::async_trait;use wasmtime::Store;use wasmtime::component::Linker;use wasmtime_wasi::{ResourceTable, WasiCtx, WasiCtxBuilder, WasiView};use crate::context::JobContext;use crate::safety::LeakDetector;use crate::secrets::SecretsStore;use crate::tools::tool::{Tool, ToolError, ToolOutput};use crate::tools::wasm::capabilities::Capabilities;use crate::tools::wasm::credential_injector::{    InjectedCredentials, host_matches_pattern, inject_credential,};use crate::tools::wasm::error::WasmError;use crate::tools::wasm::host::{HostState, LogLevel};use crate::tools::wasm::limits::{ResourceLimits, WasmResourceLimiter};use crate::tools::wasm::runtime::{EPOCH_TICK_INTERVAL, PreparedModule, WasmToolRuntime};// Generate component model bindings from the WIT file.//// This creates:// - `near::agent::host::Host` trait + `add_to_linker()` for the import interface// - `SandboxedTool` struct with `instantiate()` for the world// - `exports::near::agent::tool::*` types for the export interfacewasmtime::component::bindgen!({    path: "wit/tool.wit",    world: "sandboxed-tool",    async: false,    with: {},});// Alias the export interface types for convenience.use exports::near::agent::tool as wit_tool;/// Configuration needed to refresh an expired OAuth access token.////// Extracted at tool load time from the capabilities file's `auth.oauth` section./// Passed into `resolve_host_credentials()` so it can transparently refresh/// tokens before WASM execution.#[derive(Debug, Clone)]pub struct OAuthRefreshConfig {    /// OAuth token exchange URL (e.g., "https://oauth2.googleapis.com/token").    pub token_url: String,    /// OAuth client_id.    pub client_id: String,    /// OAuth client_secret (optional, some providers use PKCE without a secret).    pub client_secret: Option<String>,    /// Secret name of the access token (e.g., "google_oauth_token").    /// The refresh token lives at `{secret_name}_refresh_token`.    pub secret_name: String,    /// Provider hint stored alongside the refreshed secret.    pub provider: Option<String>,}/// Pre-resolved credential for host-based injection.////// Built before each WASM execution by decrypting secrets from the store./// Applied per-request by matching the URL host against `host_patterns`./// WASM tools never see the raw secret values.struct ResolvedHostCredential {    /// Host patterns this credential applies to (e.g., "www.googleapis.com").    host_patterns: Vec<String>,    /// Headers to add to matching requests (e.g., "Authorization: Bearer ...").    headers: HashMap<String, String>,    /// Query parameters to add to matching requests.    query_params: HashMap<String, String>,    /// Raw secret value for redaction in error messages.    secret_value: String,}/// Store data for WASM tool execution.////// Contains the resource limiter, host state, WASI context, and injected/// credentials. Fresh instance created per execution (NEAR pattern).struct StoreData {    limiter: WasmResourceLimiter,    host_state: HostState,    wasi: WasiCtx,    table: ResourceTable,    /// Injected credentials for URL/header placeholder substitution.    /// Keys are placeholder names like "TELEGRAM_BOT_TOKEN".    credentials: HashMap<String, String>,    /// Pre-resolved credentials for automatic host-based injection.    /// Applied by matching URL host against each credential's host_patterns.    host_credentials: Vec<ResolvedHostCredential>,    /// Dedicated tokio runtime for HTTP requests, lazily initialized.    /// Reused across multiple `http_request` calls within one execution.    http_runtime: Option<tokio::runtime::Runtime>,}impl StoreData {    fn new(        memory_limit: u64,        capabilities: Capabilities,        credentials: HashMap<String, String>,        host_credentials: Vec<ResolvedHostCredential>,    ) -> Self {        // Minimal WASI context: no filesystem, no env vars (security)        let wasi = WasiCtxBuilder::new().build();        Self {            limiter: WasmResourceLimiter::new(memory_limit),            host_state: HostState::new(capabilities),            wasi,            table: ResourceTable::new(),            credentials,            host_credentials,            http_runtime: None,        }    }    /// Inject credentials into a string by replacing placeholders.    ///    /// Replaces patterns like `{GOOGLE_ACCESS_TOKEN}` with actual values.    /// WASM tools reference credentials by placeholder, never seeing real values.    fn inject_credentials(&self, input: &str, context: &str) -> String {        let mut result = input.to_string();        for (name, value) in &self.credentials {            let placeholder = format!("{{{}}}", name);            if result.contains(&placeholder) {                tracing::debug!(                    placeholder = %placeholder,                    context = %context,                    "Replacing credential placeholder in tool request"                );                result = result.replace(&placeholder, value);            }        }        result    }    /// Replace injected credential values with `[REDACTED]` in text.    ///    /// Prevents credentials from leaking through error messages or logs.    /// reqwest::Error includes the full URL in its Display output, so any    /// error from an injected-URL request will contain the raw credential    /// unless we scrub it.    fn redact_credentials(&self, text: &str) -> String {        let mut result = text.to_string();        for (name, value) in &self.credentials {            if !value.is_empty() {                result = result.replace(value, &format!("[REDACTED:{}]", name));            }        }        for cred in &self.host_credentials {            if !cred.secret_value.is_empty() {                result = result.replace(&cred.secret_value, "[REDACTED:host_credential]");            }        }        result    }    /// Inject pre-resolved host credentials into the request.    ///    /// Matches the URL host against each resolved credential's host_patterns.    /// Matching credentials have their headers merged and query params appended.    fn inject_host_credentials(        &self,        url_host: &str,        headers: &mut HashMap<String, String>,        url: &mut String,    ) {        for cred in &self.host_credentials {            let matches = cred                .host_patterns                .iter()                .any(|pattern| host_matches_pattern(url_host, pattern));            if !matches {                continue;            }            // Merge injected headers (host credentials take precedence)            for (key, value) in &cred.headers {                headers.insert(key.clone(), value.clone());            }            // Append query parameters to URL (insert before fragment if present)            if !cred.query_params.is_empty() {                let (base, fragment) = match url.find('#') {                    Some(i) => (url[..i].to_string(), Some(url[i..].to_string())),                    None => (url.clone(), None),                };                *url = base;                let separator = if url.contains('?') { '&' } else { '?' };                for (i, (name, value)) in cred.query_params.iter().enumerate() {                    if i == 0 {                        url.push(separator);                    } else {                        url.push('&');                    }                    url.push_str(&urlencoding::encode(name));                    url.push('=');                    url.push_str(&urlencoding::encode(value));                }                if let Some(frag) = fragment {                    url.push_str(&frag);                }            }        }    }}// Provide WASI context for the WASM component.// Required because tools are compiled with wasm32-wasip2 target.impl WasiView for StoreData {    fn ctx(&mut self) -> &mut WasiCtx {        &mut self.wasi    }    fn table(&mut self) -> &mut ResourceTable {        &mut self.table    }}// Implement the generated Host trait from bindgen.//// This registers all 6 host functions under the `near:agent/host` namespace:// log, now-millis, workspace-read, http-request, secret-exists, tool-invokeimpl near::agent::host::Host for StoreData {    fn log(&mut self, level: near::agent::host::LogLevel, message: String) {        let log_level = match level {            near::agent::host::LogLevel::Trace => LogLevel::Trace,            near::agent::host::LogLevel::Debug => LogLevel::Debug,            near::agent::host::LogLevel::Info => LogLevel::Info,            near::agent::host::LogLevel::Warn => LogLevel::Warn,            near::agent::host::LogLevel::Error => LogLevel::Error,        };        let _ = self.host_state.log(log_level, message);    }    fn now_millis(&mut self) -> u64 {        self.host_state.now_millis()    }    fn workspace_read(&mut self, path: String) -> Option<String> {        self.host_state.workspace_read(&path).ok().flatten()    }    fn http_request(        &mut self,        method: String,        url: String,        headers_json: String,        body: Option<Vec<u8>>,        timeout_ms: Option<u32>,    ) -> Result<near::agent::host::HttpResponse, String> {        // Inject credentials into URL (e.g., replace {TELEGRAM_BOT_TOKEN})        let injected_url = self.inject_credentials(&url, "url");        // Check HTTP allowlist        self.host_state            .check_http_allowed(&injected_url, &method)            .map_err(|e| format!("HTTP not allowed: {}", e))?;        // Record for rate limiting        self.host_state            .record_http_request()            .map_err(|e| format!("Rate limit exceeded: {}", e))?;        // Parse headers and inject credentials into header values        let raw_headers: HashMap<String, String> =            serde_json::from_str(&headers_json).unwrap_or_default();        // Leak scan runs on WASM-provided values BEFORE host credential injection.        // This prevents false positives where the host-injected Bearer token        // (e.g., xoxb- Slack token) triggers the leak detector — WASM never saw        // the real value, so scanning the pre-injection state is correct.        // Inline the scan to avoid allocating a Vec of cloned headers.        let leak_detector = LeakDetector::new();        leak_detector            .scan_and_clean(&injected_url)            .map_err(|e| format!("Potential secret leak in URL blocked: {}", e))?;        for (name, value) in &raw_headers {            leak_detector.scan_and_clean(value).map_err(|e| {                format!("Potential secret leak in header '{}' blocked: {}", name, e)            })?;        }        if let Some(body_bytes) = body.as_deref() {            let body_str = String::from_utf8_lossy(body_bytes);            leak_detector                .scan_and_clean(&body_str)                .map_err(|e| format!("Potential secret leak in body blocked: {}", e))?;        }        let mut headers: HashMap<String, String> = raw_headers            .into_iter()            .map(|(k, v)| {                (                    k.clone(),                    self.inject_credentials(&v, &format!("header:{}", k)),                )            })            .collect();        let mut url = injected_url;        // Inject pre-resolved host credentials (Bearer tokens, API keys, etc.)        // based on the request's target host.        if let Some(host) = extract_host_from_url(&url) {            self.inject_host_credentials(&host, &mut headers, &mut url);        }        // Get the max response size from capabilities (default 10MB).        let max_response_bytes = self            .host_state            .capabilities()            .http            .as_ref()            .map(|h| h.max_response_bytes)            .unwrap_or(10 * 1024 * 1024);        // Resolve hostname and reject private/internal IPs to prevent DNS rebinding.        reject_private_ip(&url)?;        // Make HTTP request using a dedicated single-threaded runtime.        // We're inside spawn_blocking, so we can't rely on the main runtime's        // I/O driver (it may be busy with WASM compilation or other startup work).        // A dedicated runtime gives us our own I/O driver and avoids contention.        // The runtime is lazily created and reused across calls within one execution.        if self.http_runtime.is_none() {            self.http_runtime = Some(                tokio::runtime::Builder::new_current_thread()                    .enable_all()                    .build()                    .map_err(|e| format!("Failed to create HTTP runtime: {e}"))?,            );        }        let rt = self.http_runtime.as_ref().expect("just initialized"); // safety: is_none branch above guarantees Some        let result = rt.block_on(async {            let client = reqwest::Client::builder()                .connect_timeout(Duration::from_secs(10))                .redirect(reqwest::redirect::Policy::none())                .build()                .map_err(|e| format!("Failed to build HTTP client: {e}"))?;            let mut request = match method.to_uppercase().as_str() {                "GET" => client.get(&url),                "POST" => client.post(&url),                "PUT" => client.put(&url),                "DELETE" => client.delete(&url),                "PATCH" => client.patch(&url),                "HEAD" => client.head(&url),                _ => return Err(format!("Unsupported HTTP method: {}", method)),            };            for (key, value) in headers {                request = request.header(&key, &value);            }            if let Some(body_bytes) = body {                request = request.body(body_bytes);            }            // Caller-specified timeout (default 30s, max 5min)            let timeout_ms = timeout_ms.unwrap_or(30_000).min(300_000) as u64;            let timeout = Duration::from_millis(timeout_ms);            let response = request.timeout(timeout).send().await.map_err(|e| {                // Walk the full error chain for the actual root cause                let mut chain = format!("HTTP request failed: {}", e);                let mut source = std::error::Error::source(&e);                while let Some(cause) = source {                    chain.push_str(&format!(" -> {}", cause));                    source = cause.source();                }                chain            })?;            let status = response.status().as_u16();            let response_headers: HashMap<String, String> = response                .headers()                .iter()                .filter_map(|(k, v)| {                    v.to_str()                        .ok()                        .map(|v| (k.as_str().to_string(), v.to_string()))                })                .collect();            let headers_json = serde_json::to_string(&response_headers).unwrap_or_default();            // Check Content-Length header for early rejection of oversized responses.            let max_response = max_response_bytes;            if let Some(cl) = response.content_length()                && cl as usize > max_response            {                return Err(format!(                    "Response body too large: {} bytes exceeds limit of {} bytes",                    cl, max_response                ));            }            // Read body with a size cap to prevent memory exhaustion.            let body = response                .bytes()                .await                .map_err(|e| format!("Failed to read response body: {}", e))?;            if body.len() > max_response {                return Err(format!(                    "Response body too large: {} bytes exceeds limit of {} bytes",                    body.len(),                    max_response                ));            }            let body = body.to_vec();            // Leak detection on response body            if let Ok(body_str) = std::str::from_utf8(&body) {                leak_detector                    .scan_and_clean(body_str)                    .map_err(|e| format!("Potential secret leak in response: {}", e))?;            }            Ok(near::agent::host::HttpResponse {                status,                headers_json,                body,            })        });        // Redact credentials from error messages before returning to WASM        result.map_err(|e| self.redact_credentials(&e))    }    fn tool_invoke(&mut self, alias: String, _params_json: String) -> Result<String, String> {        // Validate capability and resolve alias        let _real_name = self.host_state.check_tool_invoke_allowed(&alias)?;        self.host_state.record_tool_invoke()?;        // Tool invocation requires async context and access to the tool registry,        // which aren't available inside a synchronous WASM callback.        Err("Tool invocation from WASM tools is not yet supported".to_string())    }    fn secret_exists(&mut self, name: String) -> bool {        self.host_state.secret_exists(&name)    }}/// A Tool implementation backed by a WASM component.////// Each call to `execute` creates a fresh instance for isolation.pub struct WasmToolWrapper {    /// Runtime for engine access.    runtime: Arc<WasmToolRuntime>,    /// Prepared module with compiled component.    prepared: Arc<PreparedModule>,    /// Capabilities to grant to this tool.    capabilities: Capabilities,    /// Cached description (from PreparedModule or override).    /// Stored without any tool_info hints — hints are composed at display time.    description: String,    /// Compact and discovery schemas for this tool.    schemas: WasmToolSchemas,    /// Injected credentials for HTTP requests (e.g., OAuth tokens).    /// Keys are placeholder names like "GOOGLE_ACCESS_TOKEN".    credentials: HashMap<String, String>,    /// Secrets store for resolving host-based credential injection.    /// Used in execute() to pre-decrypt secrets before WASM runs.    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,    /// OAuth refresh configuration for auto-refreshing expired tokens.    oauth_refresh: Option<OAuthRefreshConfig>,}#[derive(Debug, Clone)]struct WasmToolSchemas {    /// Compact schema advertised in the main tools array.    ///    /// This stays permissive by default to avoid serializing full exported    /// WASM schemas on every LLM call. Sidecars can override it explicitly.    advertised: serde_json::Value,    /// Full schema available for discovery and runtime parameter preparation.    ///    /// Seeded from the WASM `schema()` export at registration time, unless a    /// sidecar explicitly overrides it.    discovery: serde_json::Value,}impl WasmToolSchemas {    fn permissive_schema() -> serde_json::Value {        serde_json::json!({            "type": "object",            "properties": {},            "additionalProperties": true        })    }    fn is_permissive_schema(schema: &serde_json::Value) -> bool {        schema            .get("properties")            .and_then(|p| p.as_object())            .is_none_or(|p| p.is_empty())    }    fn typed_property_count(schema: &serde_json::Value) -> usize {        schema            .get("properties")            .and_then(|p| p.as_object())            .map(|props| {                props                    .values()                    .filter(|prop| schema_is_typed_property(prop))                    .count()            })            .unwrap_or(0)    }    fn new(discovery: serde_json::Value) -> Self {        Self {            advertised: Self::permissive_schema(),            discovery,        }    }    fn with_override(&self, schema: serde_json::Value) -> Self {        Self {            advertised: schema.clone(),            discovery: schema,        }    }    fn is_advertised_permissive(&self) -> bool {        Self::is_permissive_schema(&self.advertised)    }    fn advertised(&self) -> serde_json::Value {        self.advertised.clone()    }    fn discovery(&self) -> serde_json::Value {        self.discovery.clone()    }}impl WasmToolWrapper {    /// Create a new WASM tool wrapper.    pub fn new(        runtime: Arc<WasmToolRuntime>,        prepared: Arc<PreparedModule>,        capabilities: Capabilities,    ) -> Self {        Self {            description: prepared.description.clone(),            schemas: WasmToolSchemas::new(prepared.schema.clone()),            runtime,            prepared,            capabilities,            credentials: HashMap::new(),            secrets_store: None,            oauth_refresh: None,        }    }    /// Override the tool description.    pub fn with_description(mut self, description: impl Into<String>) -> Self {        self.description = description.into();        self    }    /// Override the parameter schema.    pub fn with_schema(mut self, schema: serde_json::Value) -> Self {        let override_typed = WasmToolSchemas::typed_property_count(&schema);        let prepared_typed = WasmToolSchemas::typed_property_count(&self.prepared.schema);        if override_typed == 0 && prepared_typed > 0 {            tracing::warn!(                tool = %self.prepared.name,                "Ignoring untyped schema override for discovery/runtime preparation and preserving extracted WASM schema"            );            self.schemas = WasmToolSchemas {                advertised: schema,                discovery: self.prepared.schema.clone(),            };        } else {            self.schemas = self.schemas.with_override(schema);        }        self    }    /// Set credentials for HTTP request placeholder injection.    pub fn with_credentials(mut self, credentials: HashMap<String, String>) -> Self {        self.credentials = credentials;        self    }    /// Set the secrets store for host-based credential injection.    ///    /// When set, credentials declared in the tool's capabilities are    /// automatically decrypted and injected into HTTP requests based    /// on the target host (e.g., Bearer token for www.googleapis.com).    pub fn with_secrets_store(mut self, store: Arc<dyn SecretsStore + Send + Sync>) -> Self {        self.secrets_store = Some(store);        self    }    /// Set OAuth refresh configuration for auto-refreshing expired tokens.    ///    /// When set, `execute()` checks the access token's `expires_at` before    /// each call and silently refreshes it using the stored refresh token.    pub fn with_oauth_refresh(mut self, config: OAuthRefreshConfig) -> Self {        self.oauth_refresh = Some(config);        self    }    /// Get the resource limits for this tool.    pub fn limits(&self) -> &ResourceLimits {        &self.prepared.limits    }    /// Add all host functions to the linker using generated bindings.    ///    /// Uses the bindgen-generated `add_to_linker` function to properly register    /// all host functions with correct component model signatures under the    /// `near:agent/host` namespace.    fn add_host_functions(linker: &mut Linker<StoreData>) -> Result<(), WasmError> {        // Add WASI support (required by components built with wasm32-wasip2)        wasmtime_wasi::add_to_linker_sync(linker)            .map_err(|e| WasmError::ConfigError(format!("Failed to add WASI functions: {}", e)))?;        // Add our custom host interface using the generated add_to_linker        near::agent::host::add_to_linker(linker, |state| state)            .map_err(|e| WasmError::ConfigError(format!("Failed to add host functions: {}", e)))?;        Ok(())    }    /// Execute the WASM tool synchronously (called from spawn_blocking).    fn execute_sync(        &self,        params: serde_json::Value,        context_json: Option<String>,        host_credentials: Vec<ResolvedHostCredential>,    ) -> Result<(String, Vec<crate::tools::wasm::host::LogEntry>), WasmError> {        let engine = self.runtime.engine();        let limits = &self.prepared.limits;        // Create store with fresh state (NEAR pattern: fresh instance per call)        let store_data = StoreData::new(            limits.memory_bytes,            self.capabilities.clone(),            self.credentials.clone(),            host_credentials,        );        let mut store = Store::new(engine, store_data);        // Configure fuel if enabled        if self.runtime.config().fuel_config.enabled {            store                .set_fuel(limits.fuel)                .map_err(|e| WasmError::ConfigError(format!("Failed to set fuel: {}", e)))?;        }        // Configure epoch deadline as a hard timeout backup.        // The epoch ticker thread increments the engine epoch every EPOCH_TICK_INTERVAL.        // Setting deadline to N means "trap after N ticks", so we compute the number        // of ticks that fit in the tool's timeout. Minimum 1 to always have a backstop.        store.epoch_deadline_trap();        let ticks = (limits.timeout.as_millis() / EPOCH_TICK_INTERVAL.as_millis()).max(1) as u64;        store.set_epoch_deadline(ticks);        // Set up resource limiter        store.limiter(|data| &mut data.limiter);        // Use the pre-compiled component (no recompilation needed)        let component = self.prepared.component().clone();        // Create linker with all host functions properly namespaced        let mut linker = Linker::new(engine);        Self::add_host_functions(&mut linker)?;        // Instantiate using the generated bindings        let instance =            SandboxedTool::instantiate(&mut store, &component, &linker).map_err(|e| {                let msg = e.to_string();                if msg.contains("near:agent") || msg.contains("import") {                    WasmError::InstantiationFailed(format!(                        "{msg}. This usually means the extension was compiled against \                         a different WIT version than the host supports. \                         Rebuild the extension against the current WIT (host: {}).",                        crate::tools::wasm::WIT_TOOL_VERSION                    ))                } else {                    WasmError::InstantiationFailed(msg)                }            })?;        // Get typed interface — used for execute.        let tool_iface = instance.near_agent_tool();        // Prepare the request        let params_json = serde_json::to_string(&params)            .map_err(|e| WasmError::InvalidResponseJson(e.to_string()))?;        let request = wit_tool::Request {            params: params_json,            context: context_json,        };        // Call execute using the generated typed interface        let response = tool_iface.call_execute(&mut store, &request).map_err(|e| {            let error_str = e.to_string();            if error_str.contains("out of fuel") {                WasmError::FuelExhausted { limit: limits.fuel }            } else if error_str.contains("unreachable") {                WasmError::Trapped("unreachable code executed".to_string())            } else {                WasmError::Trapped(error_str)            }        })?;        // Get logs from host state        let logs = store.data_mut().host_state.take_logs();        // Check for tool-level error — point the LLM to tool_info for the        // full schema instead of dumping ~3.5KB inline.        if let Some(err) = response.error {            let hint = build_tool_usage_hint(&self.prepared.name, &self.schemas.discovery());            return Err(WasmError::ToolReturnedError { message: err, hint });        }        // Return result (or empty string if none)        Ok((response.output.unwrap_or_default(), logs))    }}/// Extract metadata (description + schema) from a WASM tool by briefly/// instantiating it and calling its `description()` and `schema()` exports./// Analogous to MCP's `list_tools()` — discovers tool capabilities at load time.////// Falls back to generic description and permissive schema on failure.pub(super) fn extract_wasm_metadata(    engine: &wasmtime::Engine,    component: &wasmtime::component::Component,    limits: &ResourceLimits,) -> Result<(String, serde_json::Value), WasmError> {    let store_data = StoreData::new(        limits.memory_bytes,        Capabilities::default(),        HashMap::new(),        vec![],    );    let mut store = Store::new(engine, store_data);    // Configure fuel + epoch deadline so extraction can't hang    if let Err(e) = store.set_fuel(limits.fuel) {        tracing::debug!("Fuel not enabled for metadata extraction: {e}");    }    store.epoch_deadline_trap();    let ticks = (limits.timeout.as_millis() / EPOCH_TICK_INTERVAL.as_millis()).max(1) as u64;    store.set_epoch_deadline(ticks);    store.limiter(|data| &mut data.limiter);    // Instantiate with minimal linker    let mut linker = Linker::new(engine);    WasmToolWrapper::add_host_functions(&mut linker)?;    let instance = SandboxedTool::instantiate(&mut store, component, &linker)        .map_err(|e| WasmError::InstantiationFailed(e.to_string()))?;    let tool_iface = instance.near_agent_tool();    // Extract description (fall back to generic)    let description = tool_iface        .call_description(&mut store)        .unwrap_or_else(|_| "WASM sandboxed tool".to_string());    // Extract and parse schema (fall back to permissive)    let schema = tool_iface        .call_schema(&mut store)        .ok()        .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())        .unwrap_or_else(|| {            serde_json::json!({"type": "object", "properties": {}, "additionalProperties": true})        });    Ok((description, schema))}#[async_trait]impl Tool for WasmToolWrapper {    fn name(&self) -> &str {        &self.prepared.name    }    fn description(&self) -> &str {        &self.description    }    fn parameters_schema(&self) -> serde_json::Value {        self.schemas.advertised()    }    fn discovery_schema(&self) -> serde_json::Value {        self.schemas.discovery()    }    /// Compose the tool schema for LLM function calling.    ///    /// When the advertised schema is permissive (no typed properties), appends    /// a hint to the description directing the LLM to call `tool_info` for the    /// full parameter schema. This keeps the raw description clean while still    /// guiding the LLM.    fn schema(&self) -> crate::tools::tool::ToolSchema {        let description = if self.schemas.is_advertised_permissive() {            format!(                "{} (call tool_info(name: \"{}\", include_schema: true) for parameter schema)",                self.description, self.prepared.name            )        } else {            self.description.clone()        };        crate::tools::tool::ToolSchema {            name: self.prepared.name.clone(),            description,            parameters: self.schemas.advertised(),        }    }    async fn execute(        &self,        params: serde_json::Value,        ctx: &JobContext,    ) -> Result<ToolOutput, ToolError> {        let start = Instant::now();        let timeout = self.prepared.limits.timeout;        // Pre-resolve host credentials from secrets store (async, before blocking task).        // This decrypts the secrets once so the sync http_request() host function        // can inject them without needing async access.        //        // BUG FIX: ExtensionManager stores OAuth tokens under user_id "default"        // (hardcoded at construction in app.rs), but this was previously looking        // them up under ctx.user_id — which could be a Telegram user ID, web        // gateway user, etc. — causing credential resolution to silently fail.        // Must match the storage key until per-user credential isolation is added.        let credential_user_id = "default";        let host_credentials = resolve_host_credentials(            &self.capabilities,            self.secrets_store.as_deref(),            credential_user_id,            self.oauth_refresh.as_ref(),        )        .await;        // Serialize context for WASM        let context_json = serde_json::to_string(ctx).ok();        // Clone what we need for the blocking task        let runtime = Arc::clone(&self.runtime);        let prepared = Arc::clone(&self.prepared);        let capabilities = self.capabilities.clone();        let description = self.description.clone();        let schemas = self.schemas.clone();        let credentials = self.credentials.clone();        // Execute in blocking task with timeout        let result = tokio::time::timeout(timeout, async move {            let wrapper = WasmToolWrapper {                runtime,                prepared,                capabilities,                description,                schemas,                credentials,                secrets_store: None, // Not needed in blocking task                oauth_refresh: None, // Already used above for pre-refresh            };            tokio::task::spawn_blocking(move || {                wrapper.execute_sync(params, context_json, host_credentials)            })            .await            .map_err(|e| WasmError::ExecutionPanicked(e.to_string()))?        })        .await;        let duration = start.elapsed();        match result {            Ok(Ok((result_json, logs))) => {                // Emit collected logs                for log in logs {                    match log.level {                        LogLevel::Trace => tracing::trace!(target: "wasm_tool", "{}", log.message),                        LogLevel::Debug => tracing::debug!(target: "wasm_tool", "{}", log.message),                        LogLevel::Info => tracing::info!(target: "wasm_tool", "{}", log.message),                        LogLevel::Warn => tracing::warn!(target: "wasm_tool", "{}", log.message),                        LogLevel::Error => tracing::error!(target: "wasm_tool", "{}", log.message),                    }                }                // Parse result JSON                let result: serde_json::Value = serde_json::from_str(&result_json)                    .unwrap_or(serde_json::Value::String(result_json));                Ok(ToolOutput::success(result, duration))            }            Ok(Err(wasm_err)) => Err(wasm_err.into()),            Err(_) => Err(WasmError::Timeout(timeout).into()),        }    }    fn requires_sanitization(&self) -> bool {        // WASM tools always require sanitization, they're untrusted by definition        true    }    fn estimated_duration(&self, _params: &serde_json::Value) -> Option<Duration> {        // Use the timeout as a conservative estimate        Some(self.prepared.limits.timeout)    }    fn webhook_capability(&self) -> Option<crate::tools::wasm::WebhookCapability> {        self.capabilities.webhook.clone()    }}impl std::fmt::Debug for WasmToolWrapper {    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {        f.debug_struct("WasmToolWrapper")            .field("name", &self.prepared.name)            .field("description", &self.description)            .field("limits", &self.prepared.limits)            .finish()    }}/// Refresh an expired OAuth access token using the stored refresh token.////// Posts to the provider's token endpoint with `grant_type=refresh_token`,/// then stores the new access token (with expiry) and rotated refresh token/// (if the provider returns one).////// SSRF defense: `token_url` originates from a tool's capabilities JSON, so/// a malicious tool could point it at an internal service to exfiltrate the/// refresh token. We require HTTPS, reject private/loopback IPs (including/// DNS-resolved), and disable redirects.////// Returns `true` if the refresh succeeded, `false` otherwise.